export function sanitizeProgress(value){
 const known=new Set(lessons.map(l=>l.id));
 const completed=Array.isArray(value?.completed)?[...new Set(value.completed.filter(id=>known.has(id)))]:[];
 const dates=Array.isArray(value?.dates)?[...new Set(value.dates.filter(d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)))].slice(-366):[];
 return {version:1,completed,dates};
}
const regular=u=>lessons.filter(l=>l.unit===u&&l.type!=='checkpoint');
export const checkpointOf=u=>lessons.find(l=>l.unit===u&&l.type==='checkpoint');
export const unitPassed=(u,p)=>{const c=checkpointOf(u);return !!c&&p.completed.includes(c.id);};
export function unitOpen(u,p){if(u===1)return true;const prev=regular(u-1);return prev.length>0&&(unitPassed(u-1,p)||prev.every(l=>p.completed.includes(l.id)));}
export function nextLesson(p){return lessons.find(l=>!p.completed.includes(l.id)&&canOpen(l.id,p)&&!(l.type!=='checkpoint'&&unitPassed(l.unit,p)));}
export function canOpen(id,p){const l=lessons.find(x=>x.id===id);if(!l||!unitOpen(l.unit,p))return false;if(l.type==='checkpoint'||unitPassed(l.unit,p))return true;const ls=regular(l.unit);return ls.slice(0,ls.indexOf(l)).every(x=>p.completed.includes(x.id));}
export function totalXP(p){return lessons.filter(l=>p.completed.includes(l.id)).reduce((n,l)=>n+l.xp,0);}
export function complete(p,id,date){if(!lessons.some(l=>l.id===id)||!canOpen(id,p))return p;return sanitizeProgress({completed:[...p.completed,id],dates:[...p.dates,date]});}
export const holeId=(c,r)=>`${r<5?'t':'b'}${c}`;
export function terminals(part){return [holeId(part.col,part.row),holeId(part.col+(part.kind==='resistor'?3:1),part.row)];}
export const net=id=>id.split(':')[0];
export function buttonSides(b){const t=c=>'t'+c,d=c=>'b'+c;return b.rotated?[[t(b.col),t(b.col+2)],[d(b.col),d(b.col+2)]]:[[t(b.col),d(b.col)],[t(b.col+2),d(b.col+2)]];}
function graph(circuit,pressed=false){
 const parent=new Map();const find=x=>{if(!parent.has(x))parent.set(x,x);if(parent.get(x)!==x)parent.set(x,find(parent.get(x)));return parent.get(x);};
 const join=(a,b)=>parent.set(find(a),find(b));
 for(const [a,b] of circuit.wires)join(net(a),net(b));
 const button=circuit.parts.find(p=>p.kind==='button');
 if(button){const [l,r]=buttonSides(button);join(...l);join(...r);if(pressed)join(l[0],r[0]);}
 return (a,b)=>find(a)===find(b);
}
export function inputLevel(circuit,{pressed=false,pullup=true}={}){const same=graph(circuit,pressed);if(same('vcc','gnd')||same('gpio','gnd'))return 'SHORT';if(same('gpio22','gnd'))return 'LOW';if(same('gpio22','vcc'))return 'HIGH';return pullup?'HIGH':'FLOAT';}
export function buttonState(circuit,pullup=true){
 if(!circuit.parts.some(p=>p.kind==='button'))return {ok:false,code:'no-button',message:'First place the button across the gap in the middle of the breadboard.'};
 const up=inputLevel(circuit,{pressed:false,pullup}),down=inputLevel(circuit,{pressed:true,pullup});
 if(down==='SHORT')return {ok:false,code:'short',message:'Pressing the button shorts the supply to GND. Connect GPIO 22 to the button, not to 3V3.'};
 if(up==='LOW')return {ok:false,code:'always-low',message:'GPIO 22 is connected to GND even without a press. The button may be turned sideways, or a wire skips the button.'};
 if(down!=='LOW')return {ok:false,code:'no-path',message:'Pressing the button doesn’t connect GPIO 22 to GND. GPIO 22 goes to one side of the button, the other side goes to GND.'};
 if(up==='FLOAT')return {ok:true,code:'floating',message:'The wiring is correct, but the pull-up is off: the released pin is floating.'};
 return {ok:true,code:'button-ok',message:'Button ready: HIGH (1) when released, LOW (0) when pressed.'};
}
export function circuitState(circuit){
 const same=graph(circuit);
 if(same('gpio','gnd')||same('vcc','gnd'))return {ok:false,code:'short',message:'Supply and GND are connected directly. Remove the short-circuit wire.'};
 const led=circuit.parts.find(p=>p.kind==='led');const resistor=circuit.parts.find(p=>p.kind==='resistor');
 if(!led||!resistor)return {ok:false,code:'parts',message:'First place an LED and a 220 Ω resistor.'};
 let [anode,cathode]=terminals(led);if(led.reversed)[anode,cathode]=[cathode,anode];
 const [ra,rb]=terminals(resistor);
 if(same(anode,cathode))return {ok:false,code:'bypass-led',message:'Both LED legs are on the same strip, so there is no voltage across the LED.'};
 if((same('gpio',anode)||same('vcc',anode))&&same(cathode,'gnd'))return {ok:false,code:'no-resistor',message:'The LED is on a path that skips the resistor. Connect the resistor in series with the LED.'};
 if(same(ra,rb))return {ok:false,code:'bypass-resistor',message:'A wire joins the two ends of the resistor. Remove this bridge so it can limit the current.'};
 const viaR=(s,d)=>(same(s,ra)&&same(rb,d))||(same(s,rb)&&same(ra,d));
 if((viaR('gpio',anode)&&same(cathode,'gnd'))||(same('gpio',anode)&&viaR(cathode,'gnd')))return {ok:true,code:'powered',message:'Current path complete: GPIO 23 → resistor → LED → GND.',current:5.9};
 if((viaR('gpio',cathode)&&same(anode,'gnd'))||(same('gpio',cathode)&&viaR(anode,'gnd')))return {ok:false,code:'reversed',message:'The LED is the wrong way round. Use “Reverse LED” to swap anode and cathode.'};
 if(viaR('vcc',anode)&&same(cathode,'gnd'))return {ok:false,code:'fixed-power',message:'3V3 is a fixed supply. Use GPIO 23 so your code can control the LED in this task.'};
 return {ok:false,code:'open',message:'The current path isn’t complete yet. Trace the connections between GPIO 23, the resistor, the LED and GND.'};
}
export function makeSketch(mode,delay,pullup=true){if(mode==='button')return `const int BUTTON_PIN = 22;  // the button pulls this pin to GND\nconst int LED_PIN = 23;\n\nvoid setup() {\n  pinMode(BUTTON_PIN, ${pullup?'INPUT_PULLUP':'INPUT'});\n  pinMode(LED_PIN, OUTPUT);\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  int state = digitalRead(BUTTON_PIN);\n  Serial.println(state);\n  digitalWrite(LED_PIN, state == LOW ? HIGH : LOW);\n  delay(50);\n}\n`;return `const int LED_PIN = 23;\n\nvoid setup() {\n  pinMode(LED_PIN, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(LED_PIN, HIGH);${mode==='steady'?'':`\n  delay(${delay});\n  digitalWrite(LED_PIN, LOW);\n  delay(${delay});`}\n}\n`;}
export function bounceSignal(seed){let s=seed%2147483646+1;const rnd=()=>(s=s*16807%2147483647)/2147483647;const out=[];const push=(v,n)=>{for(let i=0;i<n;i++)out.push(v);};const chatter=to=>{for(let i=2+Math.floor(rnd()*3);i>0;i--){push(to,1+Math.floor(rnd()*2));push(1-to,1+Math.floor(rnd()*2));}push(to,1);};push(1,20);chatter(0);push(0,130);chatter(1);push(1,30);return out;}
export function debounce(signal,ms){let last=1,lastChange=-Infinity;const accepted=[];signal.forEach((v,t)=>{if(v!==last&&t-lastChange>=ms){lastChange=t;last=v;accepted.push([t,v]);}});return accepted;}
export const countPresses=(signal,ms)=>debounce(signal,ms).filter(([,v])=>v===0).length;
export function caught(press,mode,period=500){return mode==='millis'||Math.floor(press.up/period)*period>=press.down;}
export function makeTimerSketch(mode){return mode==='delay'?`void loop() {\n  int state = digitalRead(BUTTON_PIN);\n  if (state == LOW && lastState == HIGH) blinking = !blinking;\n  lastState = state;\n\n  ledOn = blinking ? !ledOn : false;\n  digitalWrite(LED_PIN, ledOn ? HIGH : LOW);\n  delay(500);   // the ESP32 ignores the button here\n}\n`:`void loop() {\n  unsigned long now = millis();\n\n  int state = digitalRead(BUTTON_PIN);\n  if (state != lastState && now - lastChange >= 50) {\n    lastChange = now;\n    lastState = state;\n    if (state == LOW) blinking = !blinking;\n  }\n\n  if (blinking && now - lastBlink >= 500) {\n    lastBlink = now;\n    ledOn = !ledOn;\n  }\n  if (!blinking) ledOn = false;\n  digitalWrite(LED_PIN, ledOn ? HIGH : LOW);\n\n  if (now - lastGreen >= 150) {   // green LED at its own pace\n    lastGreen = now;\n    greenOn = !greenOn;\n    digitalWrite(GREEN_PIN, greenOn ? HIGH : LOW);\n  }\n}\n`;}
export function makeDebounceSketch(ms){return `void loop() {\n  unsigned long now = millis();\n  int state = digitalRead(BUTTON_PIN);\n\n  if (state != lastState && now - lastChange >= ${ms}) {\n    lastChange = now;\n    lastState = state;\n    if (state == LOW) presses++;   // a new press\n  }\n}\n`;}
export function grade(questions,answers){return questions.map((q,i)=>{const a=answers[i];if(q.choices)return a===q.answer;const n=Number(String(a??'').trim().replace(',','.'));return String(a??'').trim()!==''&&Number.isFinite(n)&&Math.abs(n-q.answer)<=(q.tolerance||0);});}
export const mapRange=(x,inLo,inHi,outLo,outHi)=>inHi===inLo?outLo:Math.trunc((x-inLo)*(outHi-outLo)/(inHi-inLo))+outLo;
export const PWM_TARGETS=[25,75,10];
export const pwmValue=pct=>Math.round(pct*255/100);
export const RGB_TARGETS=[{name:'Orange',rgb:[255,128,0]},{name:'Cyan',rgb:[0,255,255]},{name:'Purple',rgb:[128,0,255]}];
export const colorClose=(a,b,tol=40)=>a.every((v,i)=>Math.abs(v-b[i])<=tol);
export function makePwmSketch(v){return `const int LED_PIN = 23;\n\nvoid setup() {\n  pinMode(LED_PIN, OUTPUT);\n}\n\nvoid loop() {\n  analogWrite(LED_PIN, ${v});   // 0 = off, 255 = full\n}\n`;}
export function makeRgbSketch([r,g,b]){return `// common cathode: long leg to GND\nconst int RED_PIN = 25, GREEN_PIN = 26, BLUE_PIN = 27;\n\nvoid loop() {\n  analogWrite(RED_PIN, ${r});\n  analogWrite(GREEN_PIN, ${g});\n  analogWrite(BLUE_PIN, ${b});\n}\n`;}
export function makeKnobSketch(inHi,outHi){return `const int POT_PIN = 34;   // ADC1: works with WiFi on\nconst int LED_PIN = 23;\n\nvoid setup() {\n  pinMode(LED_PIN, OUTPUT);\n  Serial.begin(115200);\n}\n\nvoid loop() {\n  int raw = analogRead(POT_PIN);   // 0–4095\n  int level = map(raw, 0, ${inHi}, 0, ${outHi});\n  analogWrite(LED_PIN, level);\n  Serial.println(level);\n  delay(20);\n}\n`;}
